// Use the existing release and private backup configuration; never send email.
const fs=require('node:fs'),cp=require('node:child_process'),crypto=require('node:crypto');
const {Pool}=require('/app/node_modules/pg');
const fail=code=>{throw Object.assign(Error(code),{code});};
function privateJSON(file){const s=fs.lstatSync(file);if(!s.isFile()||s.isSymbolicLink()||s.uid!==1000||(s.mode&0o077)||s.size>65536)fail('GPS_BACKUP_PRIVATE_FILE_INVALID');return JSON.parse(fs.readFileSync(file,'utf8'));}
async function main(){
 if(process.getuid()!==1000||fs.existsSync('/app/.env'))fail('GPS_BACKUP_PROCESS_INVALID');
 const runtime=privateJSON('/private/app/runtime.json'),backup=privateJSON('/private/jobs/backup.json');
 const oldFiles=['api/dist/server.js','api/scripts/backup-cycle.mjs','api/scripts/backup.mjs','package-lock.json'];
 const previousSource={volume:'petcore_delivery_ed8a7940_20261122',files:Object.fromEntries(oldFiles.map(file=>[file,crypto.createHash('sha256').update(fs.readFileSync('/previous/source/'+file)).digest('hex')]))};
 if(fs.existsSync('/previous/PETCORE-RELEASE.json')){const text=fs.readFileSync('/previous/PETCORE-RELEASE.json','utf8'),marker=JSON.parse(text);previousSource.markerSha256=crypto.createHash('sha256').update(text).digest('hex');if(/^[a-f0-9]{40}$/.test(marker.revision||''))previousSource.revision=marker.revision;}
 const source=new URL(runtime.DATABASE_URL),configured=new URL(backup.DATABASE_URL);
 if(source.hostname!=='petcore-db'||source.pathname!=='/petcore'||source.port!=='5432'||source.username!=='petcore_runtime'||source.href!==configured.href)fail('GPS_BACKUP_DATABASE_MISMATCH');
 source.searchParams.set('sslmode','verify-full');source.searchParams.set('sslrootcert','/run/petcore-ca/ca.crt');
 const allowed=/^(OBJECT_STORAGE_[A-Z_]+|BACKUP_STORAGE_[A-Z_]+|BACKUP_ENCRYPTION_KEY|BACKUP_KEY_ID)$/;
 const env={PATH:process.env.PATH,NODE_ENV:'production',NODE_EXTRA_CA_CERTS:'/run/petcore-ca/ca.crt',DATABASE_SSL:'true',DATABASE_URL:source.href,PG_DUMP_PATH:'/usr/lib/postgresql/18/bin/pg_dump',PG_RESTORE_PATH:'/usr/lib/postgresql/18/bin/pg_restore',BACKUP_RETENTION_ENABLED:'false',BACKUP_RETENTION_CONFIRM_DELETE:'NO',BACKUP_RETENTION_DAYS:'30'};
 for(const [name,value]of Object.entries({...runtime,...backup}))if(allowed.test(name)){if(typeof value!=='string'||value.includes('\0'))fail('GPS_BACKUP_CONFIG_INVALID');env[name]=value;}
 const db=new Pool({connectionString:source.href,max:1,connectionTimeoutMillis:15000});db.on('error',()=>{});
 try{
  if(!(await db.query('SELECT ssl FROM pg_stat_ssl WHERE pid=pg_backend_pid()')).rows[0]?.ssl)fail('GPS_BACKUP_TLS_REQUIRED');
  const before=(await db.query('SELECT id,state,sha256,size_bytes FROM backup_runs ORDER BY id')).rows;
  const child=cp.spawnSync(process.execPath,['/app/api/scripts/backup-cycle.mjs'],{cwd:'/app',env,encoding:'utf8',stdio:['ignore','pipe','pipe'],maxBuffer:2*1024*1024,timeout:90*60*1000});
  const output=String(child.stdout||'').trim().split('\n').map(line=>{try{return JSON.parse(line);}catch{return null;}});
  const created=output.filter(row=>row?.event==='backup_created'),retention=output.find(row=>row?.event==='backup_retention');
  if(child.error||child.status!==0||created.length!==1||!created[0].ok||!retention?.ok||retention.mode!=='dry-run'||retention.expired!==0)fail('GPS_BACKUP_CYCLE_FAILED');
  const proof=created[0];if(!/^[a-f0-9-]{36}$/.test(proof.backupId||'')||!/^[a-f0-9]{64}$/.test(proof.sha256||'')||!proof.objectsIncluded||!Number.isSafeInteger(proof.sizeBytes)||proof.sizeBytes<1)fail('GPS_BACKUP_RESULT_INVALID');
  const after=(await db.query('SELECT id,state,sha256,size_bytes FROM backup_runs ORDER BY id')).rows;
  if(before.some(old=>JSON.stringify(after.find(row=>row.id===old.id))!==JSON.stringify(old)))fail('GPS_BACKUP_PREVIOUS_RECORD_CHANGED');
  const row=(await db.query("SELECT sha256,size_bytes FROM backup_runs WHERE id=$1 AND state='uploaded' AND retention_scope='active' AND finished_at IS NOT NULL",[proof.backupId])).rows[0];
  if(!row||row.sha256!==proof.sha256||Number(row.size_bytes)!==proof.sizeBytes)fail('GPS_BACKUP_RECORD_MISMATCH');
  console.log(JSON.stringify({ok:true,event:'petcore_gps_pre_migration_backup',backupId:proof.backupId,sha256:proof.sha256,sizeBytes:proof.sizeBytes,objectsIncluded:true,retentionDryRun:true,previousRecordsPreserved:true,restorationVerified:false,previousSource}));
 }finally{await db.end();}
}
main().catch(error=>{console.error(JSON.stringify({ok:false,code:/^GPS_BACKUP_[A-Z_]+$/.test(error.code||'')?error.code:'GPS_BACKUP_FAILED'}));process.exitCode=1;});
